<nav class="plan-actions" aria-label="Related swimming reports"><?php foreach(array('volume'=>'Training Volume','trends'=>'Training Trends','pool'=>'Pool Analytics')as$reportScreen=>$label):$args=array('screen'=>$reportScreen,'months'=>$months??$v['months']);if($reportScreen!=='trends'){if(isset($course)&&in_array($course,array('m','yd'),true))$args['course']=$course;if(isset($stroke)&&is_string($stroke)&&$stroke!=='')$args['stroke']=$stroke;} ?><a class="control" href="<?php echo esc_url('/?'.http_build_query($args)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
